cd /root/.claude/projects/-home-user-fortress/ && python3 - <<'EOF'
import json
ds=[]
with open('fe616d40-a9c6-56d7-9da1-7168a172765d.jsonl','rb') as f:
    for line in f:
        if b'stop_hook_summary' not in line: continue
        try: r=json.loads(line)
        except Exception: continue
